import {icon} from './icons.js';
const pets=[{id:'luna',name:'Orbit',role:'Fokus və plan',color:'#7f94b2',file:'orbit.svg'},{id:'milo',name:'Nova',role:'Rəqəmsal köməkçi',color:'#7faaa9',file:'nova.svg'},{id:'peach',name:'Prism',role:'İdeya və aydınlıq',color:'#a396bc',file:'prism.svg'}];
const tips={home:['Bu gün üçün bir əsas iş seç. Kiçik addımla başlamaq kifayətdir.','Bir işi tamamlayanda işarələ. İrəliləyişini görmək yaxşı hissdir.','Planında özün üçün də bir az boş vaxt saxla.'],notes:['Fikrini itirmədən yaz. Başlığı sonra da dəyişə bilərsən.','Vacib qeydi sabitlə ki, həmişə əl altında olsun.','Qısa başlıq və bir ilk addım: yaxşı qeydin başlanğıcı budur.'],discover:['Əhvalını seç, bu axşama uyğun üç film tapaq.','Bəyəndiyin filmi izləniləcək siyahıya əlavə edə bilərsən.','Uzun gündən sonra yüngül bir hekayə necə olar?'],ai:['Auto rejimində uyğun provayderi ASTRA seçir.','Böyük sualı kiçik hissələrə bölmək cavabı daha aydın edir.','AI cavabındakı vacib faktları mənbə ilə yoxlamaq faydalıdır.'],admin:['Admin əməliyyatları serverdə yoxlanılır və qeydə alınır.']};
let state={selected:['luna'],quiet:false};try{const saved=JSON.parse(localStorage.getItem('astra-pets')||'null');if(saved)state={selected:Array.isArray(saved.selected)?saved.selected.filter(id=>pets.some(p=>p.id===id)):['luna'],quiet:!!saved.quiet};}catch{}

const page=document.body.dataset.page,base=document.body.dataset.admin==='true'?'../':'./';let index=0,active=state.selected[0]||'luna';
const root=document.createElement('aside');root.className='pet-widget';root.setAttribute('aria-label','ASTRA rəqəmsal köməkçilər');document.body.append(root);
function save(){try{localStorage.setItem('astra-pets',JSON.stringify(state));}catch{}}
function image(p,cls=''){return `<img class="${cls}" src="${base}assets/images/pets/${p.file}" alt="${p.name}" draggable="false">`;}
function render(){const chosen=pets.filter(p=>state.selected.includes(p.id));root.innerHTML=`<section class="pet-panel" id="pet-panel" aria-label="Köməkçi seçimi" hidden><header><div><strong>Rəqəmsal yoldaşlar</strong><p>İş üslubuna uyğun köməkçini seç.</p></div><button class="icon-btn" data-pet="close" aria-label="Köməkçi seçimini bağla">${icon('close')}</button></header><div class="pet-choices">${pets.map(p=>`<button class="pet-choice ${state.selected.includes(p.id)?'selected':''}" data-pet="select:${p.id}" aria-pressed="${state.selected.includes(p.id)}" style="--pet-color:${p.color}">${image(p)}<strong>${p.name}</strong><small>${p.role}</small><span class="pet-check">${state.selected.includes(p.id)?'✓':'＋'}</span></button>`).join('')}</div><label class="pet-quiet"><input type="checkbox" id="pet-quiet" ${state.quiet?'checked':''}> Sakit rejim — məsləhət balonunu gizlət</label><p class="pet-privacy">Yoldaş modulu ekranı çəkmir və kursor məlumatını göndərmir. Buradakı qısa məsləhətlər hazır interfeys mətnləridir, AI cavabı deyil.</p></section><div class="pet-tip" id="pet-tip" ${state.quiet||!chosen.length?'hidden':''}><button class="pet-tip-close" data-pet="dismiss" aria-label="Məsləhəti gizlət">${icon('close')}</button><span class="pet-tip-label">${pets.find(p=>p.id===active)?.name||'Orbit'} deyir</span><p id="pet-tip-text"></p><button class="pet-next" data-pet="tip">Başqa məsləhət ${icon('ai')}</button></div><div class="pet-dock">${chosen.map(p=>`<button class="pet-character ${p.id===active?'speaking':''}" data-pet="talk:${p.id}" aria-label="${p.name} ilə məsləhət al" style="--pet-color:${p.color}"><span class="pet-body">${image(p)}<span class="pet-gaze" aria-hidden="true"><i></i><i></i></span></span><span class="pet-name">${p.name}</span></button>`).join('')}<button class="pet-add" data-pet="open" aria-label="Köməkçiləri seç" aria-expanded="false" aria-controls="pet-panel">${icon(chosen.length?'plus':'ai')}<span>${chosen.length?'Yoldaşlar':'Köməkçi seç'}</span></button></div>`;tip(false);root.querySelector('#pet-quiet').onchange=e=>{state.quiet=e.target.checked;save();root.querySelector('#pet-tip').hidden=state.quiet||!chosen.length;};}
function tip(advance=true){if(advance)index++;const list=tips[page]||tips.admin;root.querySelector('#pet-tip-text').textContent=list[index%list.length];}
root.addEventListener('click',e=>{const b=e.target.closest('[data-pet]');if(!b)return;const [action,id]=b.dataset.pet.split(':');if(action==='open'||action==='close'){const open=action==='open';root.querySelector('#pet-panel').hidden=!open;root.querySelector('.pet-add').setAttribute('aria-expanded',String(open));if(open)root.querySelector('[data-pet="close"]').focus();else root.querySelector('.pet-add').focus();}if(action==='select'){const focusId=id;state.selected=state.selected.includes(id)?state.selected.filter(x=>x!==id):[...state.selected,id];active=state.selected.includes(active)?active:state.selected[0];save();render();root.querySelector('#pet-panel').hidden=false;root.querySelector('.pet-add').setAttribute('aria-expanded','true');root.querySelector(`[data-pet="select:${focusId}"]`).focus();}if(action==='talk'){active=id;state.quiet=false;save();render();tip();}if(action==='tip')tip();if(action==='dismiss'){state.quiet=true;save();root.querySelector('#pet-tip').hidden=true;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!root.querySelector('#pet-panel').hidden){root.querySelector('#pet-panel').hidden=true;root.querySelector('.pet-add').setAttribute('aria-expanded','false');root.querySelector('.pet-add').focus();}});
let frame;document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{for(const b of root.querySelectorAll('.pet-character')){const r=b.getBoundingClientRect(),x=Math.max(-3,Math.min(3,(e.clientX-r.left-r.width/2)/65)),y=Math.max(-2,Math.min(2,(e.clientY-r.top-r.height/2)/80));b.style.setProperty('--look-x',x+'px');b.style.setProperty('--look-y',y+'px');}});},{passive:true});
document.addEventListener('click',e=>{if(e.target.closest('[data-action^="task:"]')){const p=root.querySelector('#pet-tip-text');if(p)p.textContent='Bir addım da irəli! Planını öz ritminə uyğun davam etdir.';}});
render();
